/*
 * Builds the bundled fallback puzzle pool inside engine.js.
 *
 * Run from the project root:  node scripts/build-pool.js
 * Every entry is generated by the engine itself, then verified again here:
 * N connected regions, one capybara per row/column/region, no touching, and
 * exactly one solution.
 */
'use strict';

const fs = require('fs');
const path = require('path');
const Engine = require(path.join(__dirname, '..', 'engine.js'));

const WANTED = [
  [5, 8],
  [6, 8],
  [7, 12],
  [8, 16],
  [9, 24],
  [10, 60]
];

function regionSizes(regions, size) {
  const sizes = new Array(size).fill(0);
  for (const rid of regions) sizes[rid]++;
  return sizes;
}

function connected(regions, size, rid) {
  const cells = [];
  for (let i = 0; i < size * size; i++) if (regions[i] === rid) cells.push(i);
  const inside = new Set(cells);
  const seen = new Set([cells[0]]);
  const stack = [cells[0]];
  while (stack.length) {
    const cur = stack.pop();
    const r = Math.floor(cur / size);
    const c = cur % size;
    for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const rr = r + dr;
      const cc = c + dc;
      if (rr < 0 || cc < 0 || rr >= size || cc >= size) continue;
      const ni = rr * size + cc;
      if (inside.has(ni) && !seen.has(ni)) {
        seen.add(ni);
        stack.push(ni);
      }
    }
  }
  return seen.size === cells.length;
}

function verified(puzzle) {
  const { size, regions, solution } = puzzle;
  const sizes = regionSizes(regions, size);
  if (sizes.some((s) => s < 1)) return false;
  const rules = Engine.rulesFor(size);
  if (sizes.some((s) => s < rules.minRegion || s > rules.maxRegion)) return false;
  for (let rid = 0; rid < size; rid++) if (!connected(regions, size, rid)) return false;
  if (!Engine.isSolved(regions, size, solution.map((col, row) => row * size + col))) return false;
  return Engine.countSolutions(regions, size, 2) === 1;
}

const pool = {};
for (const [size, wanted] of WANTED) {
  pool[size] = [];
  let seedIndex = 0;
  while (pool[size].length < wanted && seedIndex < wanted * 6) {
    const seed = `pool-${size}-${seedIndex++}`;
    const puzzle = Engine.generatePuzzle(size, seed);
    if (puzzle.source !== 'generated') continue;
    if (!verified(puzzle)) throw new Error(`pool puzzle failed verification: ${seed}`);
    pool[size].push({
      r: Engine.encodeRegions(puzzle.regions),
      s: Engine.encodeSolution(puzzle.solution)
    });
  }
  if (pool[size].length < wanted) throw new Error(`only built ${pool[size].length}/${wanted} for ${size}`);
  console.log(`size ${size}: ${pool[size].length} puzzles`);
}

const enginePath = path.join(__dirname, '..', 'engine.js');
let source = fs.readFileSync(enginePath, 'utf8');
const literal = Object.keys(pool)
  .map((size) => {
    const rows = pool[size].map((e) => `      { r: '${e.r}', s: '${e.s}' }`).join(',\n');
    return `    ${size}: [\n${rows}\n    ]`;
  })
  .join(',\n');
const block = `  var FALLBACK_POOL = {\n${literal}\n  };`;
const pattern = /  var FALLBACK_POOL = \{[\s\S]*?\n  \};/;
if (!pattern.test(source)) throw new Error('FALLBACK_POOL block not found');
source = source.replace(pattern, block);
fs.writeFileSync(enginePath, source);
console.log('engine.js updated');
